    lower, upper = 0, 1
    if counts != 0:
        lower = beta.ppf(alpha / 2, counts, shots - counts + 1)
    # if counts == shots, the beta quantile returns nan
    if counts != shots:
        upper = beta.ppf(1 - alpha / 2, counts + 1, shots - counts)
    return lower, upper

